const SYNODIC_MONTH_DAYS = 29.530588861;const REFERENCE_NEW_MOON_UTC = Date.UTC(2000, 0, 6, 18, 14, 0); function moonPhaseFraction(date){const daysSince = (date.getTime() - REFERENCE_NEW_MOON_UTC) / 86400000;const phaseDays = ((daysSince % SYNODIC_MONTH_DAYS) + SYNODIC_MONTH_DAYS) % SYNODIC_MONTH_DAYS;return{phaseDays, fraction: phaseDays / SYNODIC_MONTH_DAYS};}function moonIlluminationPercent(fraction){return (1 - Math.cos(2 * Math.PI * fraction)) / 2 * 100;}const MOON_PHASE_NAMES = [ "New Moon", "Waxing Crescent", "First Quarter", "Waxing Gibbous", "Full Moon", "Waning Gibbous", "Last Quarter", "Waning Crescent", ];function moonPhaseName(fraction){ const shifted = (fraction + 1 / 16) % 1;const index = Math.floor(shifted * 8) % 8;return MOON_PHASE_NAMES[index];}function moonDaysUntilFull(phaseDays){const half = SYNODIC_MONTH_DAYS / 2;return phaseDays <= half ? half - phaseDays : SYNODIC_MONTH_DAYS - phaseDays + half;}function moonDaysUntilNew(phaseDays){return phaseDays === 0 ? 0 : SYNODIC_MONTH_DAYS - phaseDays;}function computeMoonPhase(date){const{phaseDays, fraction}= moonPhaseFraction(date);return{phaseDays, fraction, illumination: moonIlluminationPercent(fraction), name: moonPhaseName(fraction), daysUntilFull: moonDaysUntilFull(phaseDays), daysUntilNew: moonDaysUntilNew(phaseDays),};}const MOON_FACES = ["\u{1F311}", "\u{1F312}", "\u{1F313}", "\u{1F314}", "\u{1F315}", "\u{1F316}", "\u{1F317}", "\u{1F318}"];function executeMoonPhase(){const dateInput = document.getElementById("moon-date").value;const date = dateInput ? new Date(dateInput + "T12:00:00Z") : new Date();const m = computeMoonPhase(date);const faceIndex = MOON_PHASE_NAMES.indexOf(m.name);const out = document.getElementById("moon-result");out.innerHTML = `
    <div style="font-size:3rem; text-align:center;">${MOON_FACES[faceIndex]}</div>
    <div style="text-align:center; font-size:1.1rem; margin-top:0.5rem;">${m.name}</div>
    <div class="iifym-macros" style="margin-top:1rem;">
      <div class="iifym-macro"><span class="iifym-macro-label">Illumination</span><span class="iifym-macro-val">${m.illumination.toFixed(1)}%</span></div>
      <div class="iifym-macro"><span class="iifym-macro-label">Days since new</span><span class="iifym-macro-val">${m.phaseDays.toFixed(1)}</span></div>
      <div class="iifym-macro"><span class="iifym-macro-label">Days to full</span><span class="iifym-macro-val">${m.daysUntilFull.toFixed(1)}</span></div>
      <div class="iifym-macro"><span class="iifym-macro-label">Days to new</span><span class="iifym-macro-val">${m.daysUntilNew.toFixed(1)}</span></div>
    </div>
  `;GAMA.say("success");GAMA.log(`Moon phase for ${date.toISOString().slice(0, 10)}: ${m.name}, ${m.illumination.toFixed(0)}% lit`);}document.addEventListener("DOMContentLoaded", () =>{const dateInput = document.getElementById("moon-date");if (dateInput){dateInput.valueAsDate = new Date();executeMoonPhase();}});